import{_ as o,l as s,o as a,c,v as r,p as n,x as i,d as l,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"缓存侧信道 Prime+Probe","description":"","frontmatter":{"title":"缓存侧信道 Prime+Probe","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-side-channel.md","filePath":"cs/cache-side-channel.md","lastUpdated":1789023840000}'),p={name:"cs/cache-side-channel.md"};function m(E,e,f,A,B,_){const t=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="缓存侧信道-prime-probe" tabindex="-1">缓存侧信道 Prime+Probe <a class="header-anchor" href="#缓存侧信道-prime-probe" aria-label="Permalink to &quot;缓存侧信道 Prime+Probe&quot;">​</a></h1><div class="epigraph"><p>共享 cache 的组是可观测的：先填满一组，等受害者执行，再测自己的行还在不在。命中延迟编码的是「谁碰过这一组」，不是 ISA 寄存器。</p><footer>—— 据 Osvik, Shamir, and Tromer, Cache Attacks and Countermeasures, CT-RSA 2006 整理</footer></div><p><a href="/cs/rowhammer">上一课</a> 改 DRAM 电荷。<a href="/cs/spectre-variants">Spectre</a> 把瞬态 load 编进占用。即使没有瞬态，两个进程共享 LLC 时，<a href="/cs/cache-partition-qos">分区</a> 若未切开，组相联本身就是信道。本课收束微结构进阶：只讲 <strong>Prime+Probe 的机制与防御方向</strong>，不给探测实现，不接量化 LOB，不重写 Transformer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/locality-principle">局部性</a> 让硬件共享 SRAM。<a href="/cs/way-prediction">路预测</a> 与 LRU 状态也因访问而变。测量者若能让自己的行与受害者映射到同一组，就可以用命中/缺失延迟读出「组是否被动过」。缺口不是再训 TAGE，而是<strong>把 cache 替换状态标成非架构输出</strong>，与 <a href="/cs/transient-exec">瞬态执行对照</a> 同一威胁模型。</p><p><span class="marginnote">Osvik–Shamir–Tromer 系统化 Prime+Probe（以及 Evict+Time 等）。Flush+Reload 依赖共享页，机制不同、同属缓存信道。防御：分区、隔离、常量时间、限制高分辨率计时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>机制上分三步直觉：准备（使一组处于已知占用）、等待（受害者运行）、探测（再访问自己的行，看延迟）。防御：LLC 按核/QoS 切 way，减少跨域同组；常数时间密码实现不按秘密索引 cache；关闭或噪声化对侧的计时。本课不写如何选冲突集。</p>',8)),(a(),n(d,null,{default:i(()=>[h(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIME%5B%22%E5%8D%A0%E6%BB%A1%E7%9B%AE%E6%A0%87%E7%BB%84%22%5D%20--%3E%20WAIT%5B%22%E5%8F%97%E5%AE%B3%E8%80%85%E8%AE%BF%E5%AD%98%22%5D%0A%20%20WAIT%20--%3E%20PROBE%5B%22%E5%86%8D%E8%AE%BF%E5%B7%B1%E6%96%B9%E8%A1%8C%E6%B5%8B%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20PART%5B%22%E8%B7%AF%E5%88%86%E5%8C%BA%20%2F%20%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20CUT%5B%22%E8%B7%A8%E5%9F%9F%E5%90%8C%E7%BB%84%E5%87%8F%E5%B0%91%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 <a href="/cs/false-sharing">伪共享</a>：都是行/组粒度的意外共享；一个打性能，一个当信道。与 PMU：计数器与 <code>rdtsc</code> 都是时钟。<a href="/cs/fence-cost">fence</a> 不能单独关掉占用。本课程到此：前端预测、乱序窗口、cache 协议、SIMT、互连、测量与故障，全部会在安全边界上重现为副作用。</p><p>inclusive LLC 让私有 L1 的占用更容易反映到共享层，exclusive 则相反。这不是选 inclusive 的理由，只是信道带宽的几何。后课（数据结构进阶）不再续这条微结构链；本课是单元收口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供可运行的探测、不讨论绕过具体云隔离的步骤。密码实现的常数时间是软件课/安全课的接口。微结构进阶结束：下一课程从<a href="/cs/prefix-sum-difference">前缀和与差分</a>起，默认已经读过推测、一致性与这些副作用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Prime+Probe 用组相联占用与命中延迟做信道。</li><li>分区与隔离减少跨域同组；不能单靠 ISA 正确性。</li><li>微结构进阶在此收口：性能机制即安全边界。</li><li>出处：Osvik, Shamir, Tromer, <em>CT-RSA</em>, 2006；Kocher 等时序一线。</li></ul>',7))])}const T=o(p,[["render",m]]);export{u as __pageData,T as default};
